export const leadsUnified = pgView("leads_unified", {	id: uuid(),
	sourceId: uuid("source_id"),
	source: text(),
	location: text(),
	country: text(),
	company: text(),
	legalName: text("legal_name"),
	domain: text(),
	industry: text(),
	companySize: text("company_size"),
	businessModel: text("business_model"),
	accountStatus: text("account_status"),
	recommendedAction: text("recommended_action"),
	fitScore: integer("fit_score"),
	intentScore: integer("intent_score"),
	totalScore: integer("total_score"),
	confidence: numeric(),
	intentSummary: text("intent_summary"),
	workflowPain: text("workflow_pain"),
	conversationAngle: text("conversation_angle"),
	productLine: text("product_line"),
	evidence: jsonb(),
	scoreReasons: jsonb("score_reasons"),
	uncertainty: jsonb(),
	sourceUrls: text("source_urls"),
	exclusionFlags: text("exclusion_flags"),
	// You can use { mode: "bigint" } if numbers are exceeding js number limitations
	contactCount: bigint("contact_count", { mode: "number" }),
	// You can use { mode: "bigint" } if numbers are exceeding js number limitations
	verifiedContactCount: bigint("verified_contact_count", { mode: "number" }),
	contactName: text("contact_name"),
	contactTitle: text("contact_title"),
	contactEmail: text("contact_email"),
	emailStatus: text("email_status"),
	emailVerified: boolean("email_verified"),
	emailConfidence: numeric("email_confidence"),
	emailSourceUrl: text("email_source_url"),
	contactLinkedinUrl: text("contact_linkedin_url"),
	contactPhone: text("contact_phone"),
	contacts: jsonb(),
	outreachId: uuid("outreach_id"),
	outreachStatus: text("outreach_status"),
	outreachChannel: text("outreach_channel"),
	outreachSubject: text("outreach_subject"),
	outreachBody: text("outreach_body"),
	outreachToEmail: text("outreach_to_email"),
	outreachVersion: integer("outreach_version"),
	draftedAt: timestamp("drafted_at", { withTimezone: true, mode: 'string' }),
	approvedAt: timestamp("approved_at", { withTimezone: true, mode: 'string' }),
	sentAt: timestamp("sent_at", { withTimezone: true, mode: 'string' }),
	discoveryDate: date("discovery_date"),
	lastResearchedAt: timestamp("last_researched_at", { withTimezone: true, mode: 'string' }),
	companyId: uuid("company_id"),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }),
}).as(sql`WITH contact_pick AS ( SELECT DISTINCT ON (c.account_id) c.account_id, c.id AS contact_id, c.full_name, c.role, c.email, c.email_status, c.email_confidence, c.email_source_url, c.linkedin_url, c.phone FROM sales_contacts c WHERE NOT c.suppressed ORDER BY c.account_id, ( CASE c.email_status WHEN 'verified'::text THEN 0 WHEN 'found_publicly'::text THEN 1 WHEN 'suggested'::text THEN 2 WHEN 'unknown'::text THEN 3 ELSE 4 END), (c.email IS NULL), c.created_at ), contact_counts AS ( SELECT sales_contacts.account_id, count(*) AS contact_count, count(*) FILTER (WHERE sales_contacts.email_status = 'verified'::text) AS verified_contact_count, jsonb_agg(jsonb_build_object('id', sales_contacts.id, 'name', sales_contacts.full_name, 'title', sales_contacts.role, 'email', sales_contacts.email, 'email_status', sales_contacts.email_status, 'email_confidence', sales_contacts.email_confidence, 'email_source_url', sales_contacts.email_source_url, 'linkedin_url', sales_contacts.linkedin_url, 'phone', sales_contacts.phone, 'phone_status', sales_contacts.phone_status) ORDER BY sales_contacts.created_at) AS contacts FROM sales_contacts GROUP BY sales_contacts.account_id ), draft_pick AS ( SELECT DISTINCT ON (o.account_id) o.account_id, o.id AS outreach_id, o.status AS outreach_status, o.channel AS outreach_channel, o.subject AS outreach_subject, o.body AS outreach_body, o.email AS outreach_to_email, o.version AS outreach_version, o.created_at AS drafted_at, o.approved_at, o.sent_at FROM sales_outreach o ORDER BY o.account_id, o.version DESC, o.created_at DESC ) SELECT a.id, a.id AS source_id, a.source, a.location, a.country, COALESCE(a.trading_name, a.legal_name) AS company, a.legal_name, a.domain, a.industry, a.company_size_estimate AS company_size, a.business_model, a.status AS account_status, a.recommended_action, a.fit_score, a.intent_score, a.total_score, a.confidence, a.business_trigger AS intent_summary, a.workflow_pain, a.conversation_angle, a.product_line, a.score_evidence AS evidence, a.score_reasons, a.score_uncertainty AS uncertainty, a.source_urls, a.exclusion_flags, COALESCE(cc.contact_count, 0::bigint) AS contact_count, COALESCE(cc.verified_contact_count, 0::bigint) AS verified_contact_count, cp.full_name AS contact_name, cp.role AS contact_title, cp.email AS contact_email, cp.email_status, cp.email_status = 'verified'::text AS email_verified, cp.email_confidence, cp.email_source_url, cp.linkedin_url AS contact_linkedin_url, cp.phone AS contact_phone, cc.contacts, dp.outreach_id, dp.outreach_status, dp.outreach_channel, dp.outreach_subject, dp.outreach_body, dp.outreach_to_email, dp.outreach_version, dp.drafted_at, dp.approved_at, dp.sent_at, a.discovery_date, a.last_researched_at, a.company_id, a.created_at, a.updated_at FROM sales_accounts a LEFT JOIN contact_pick cp ON cp.account_id = a.id LEFT JOIN contact_counts cc ON cc.account_id = a.id LEFT JOIN draft_pick dp ON dp.account_id = a.id`);

